package com.trampolim.api.observatory;
import java.util.*;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.util.function.Supplier;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
/** Local prepared aggregates only. Web requests never execute a capture. */
public abstract class SnapshotBatch {
 protected static final ZoneId ZONE=ZoneId.of("America/Sao_Paulo");protected final JdbcTemplate db;private final TransactionTemplate write,read;private final AtomicBoolean busy=new AtomicBoolean();private final ExecutorService executor=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"observatory-capture");t.setDaemon(true);return t;});private volatile String lastResult="NOT_RUN";
 protected SnapshotBatch(JdbcTemplate db,PlatformTransactionManager manager){this.db=db;write=new TransactionTemplate(manager);write.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);read=new TransactionTemplate(manager);read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);read.setReadOnly(true);}
 public Map<String,Object> enqueue(){if(!busy.compareAndSet(false,true))return Map.of("queued",false,"state","ALREADY_RUNNING");executor.execute(()->{try{captureWork();lastResult="SUCCESS";}catch(Exception error){lastResult="FAILED";org.slf4j.LoggerFactory.getLogger(getClass()).warn("Observatory batch failed; prior committed generation preserved ({})",error.getClass().getSimpleName());}finally{busy.set(false);}});return Map.of("queued",true,"state","QUEUED");}
 public boolean capture(){if(!busy.compareAndSet(false,true))return false;try{boolean done=captureWork();lastResult=done?"SUCCESS":"BUSY_OTHER_INSTANCE";return done;}finally{busy.set(false);}}
 private boolean captureWork(){return Boolean.TRUE.equals(write.execute(status->{db.execute("SET LOCAL statement_timeout='30s'");db.execute("SET LOCAL lock_timeout='3s'");if(!Boolean.TRUE.equals(db.queryForObject("SELECT pg_try_advisory_xact_lock(hashtextextended(current_schema()||':observatory-v2',0))",Boolean.class)))return false;long epoch=db.queryForObject("SELECT revision FROM observatory_epoch WHERE id=1 FOR SHARE",Long.class);Instant observed=Instant.now();LocalDate through=observed.atZone(ZONE).toLocalDate(),from=through.minusMonths(12).withDayOfMonth(1);UUID id=UUID.randomUUID();db.update("INSERT INTO observatory_runs(id,epoch,observed_at,coverage_from,coverage_through) VALUES (?,?,?,?,?)",id,epoch,java.sql.Timestamp.from(observed),from,through);build(id,from,observed);db.update("DELETE FROM observatory_runs WHERE id NOT IN (SELECT id FROM observatory_runs ORDER BY observed_at DESC LIMIT 2)");return true;}));}
 protected abstract void build(UUID id,LocalDate from,Instant observed);
 protected <T>T read(Supplier<T> work){return read.execute(status->{db.execute("SET LOCAL statement_timeout='3s'");return work.get();});}
 protected Map<String,Object> current(){var rows=db.queryForList("SELECT r.*,e.revision AS current_epoch FROM observatory_runs r CROSS JOIN observatory_epoch e WHERE e.id=1 ORDER BY r.observed_at DESC LIMIT 1");if(rows.isEmpty())return Map.of("status","NOT_CAPTURED");var r=rows.getFirst();String state=((Number)r.get("epoch")).longValue()!=((Number)r.get("current_epoch")).longValue()?"INVALIDATED":((java.sql.Timestamp)r.get("observed_at")).toInstant().isBefore(Instant.now().minus(Duration.ofHours(2)))?"STALE":"READY";r.put("status",state);return r;}
 public Map<String,Object> health(){return read(()->{var r=current();var out=new LinkedHashMap<String,Object>();out.put("status",r.get("status"));out.put("running",busy.get());out.put("lastAttempt",lastResult);if(r.get("observed_at")!=null)out.put("observedAt",r.get("observed_at"));return out;});}
 protected static long count(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 public static Map<String,Object> privateBand(long value,long people,long organizations,boolean corporate){if(value<10||people<10||corporate&&organizations<3)return Map.of("available",false,"status","SUPPRESSED","reason","Grupo insuficiente para divulgação.");long lower=value/10*10;return Map.of("available",true,"status","AVAILABLE","lowerBound",lower,"upperBound",lower+9,"label",lower+"–"+(lower+9));}
 protected static YearMonth month(String text){try{if(text==null||!text.matches("[0-9]{4}-[0-9]{2}"))throw new IllegalArgumentException();return YearMonth.parse(text);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Informe mês no formato AAAA-MM.");}}
 protected static void period(String from,String to){YearMonth a=month(from),b=month(to);if(b.isBefore(a)||a.plusMonths(11).isBefore(b)||b.isAfter(YearMonth.now(ZONE)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Consulte de um a doze meses, sem meses futuros.");}
 @jakarta.annotation.PreDestroy public void close(){executor.shutdownNow();}
}
